INSERT INTO questions (question, options, correct_index, difficulty, category, explanation, topic, campaign) VALUES
('ഇന്ത്യയിൽ NPS നടപ്പാക്കിയ സമയത്ത് അധികാരത്തിലുണ്ടായിരുന്ന കേന്ദ്രസർക്കാർ ഏത്?', '["കോൺഗ്രസ് നേതൃത്വത്തിലുള്ള UPA","ജനതാദൾ സർക്കാർ","NDA – അടൽ ബിഹാരി വാജ്പേയി സർക്കാർ","ഒന്നാം മോദി സർക്കാർ"]'::jsonb, 2, 'medium', 'Political', '2003 ഡിസംബറിൽ വാജ്പേയി നേതൃത്വം നൽകിയ NDA സർക്കാരാണ് NPS വിജ്ഞാപനം ചെയ്തത്; 2004 ജനുവരി 1 മുതൽ ഇത് പ്രാബല്യത്തിൽ വന്നു.', 'central-govt', false),
('ഇന്ത്യയിൽ കേന്ദ്രസർക്കാർ ജീവനക്കാർക്കായി NPS നിർബന്ധമാക്കിയ തീയതി ഏത്?', '["01-01-2003","01-01-2004","01-04-2004","01-01-2005"]'::jsonb, 1, 'easy', 'Political', '01-01-2004-നോ അതിനുശേഷമോ കേന്ദ്ര സർവീസിൽ പ്രവേശിച്ചവർക്ക് (സായുധസേന ഒഴികെ) NPS നിർബന്ധമാണ്.', 'central-date', false),
('NPS നടപ്പാക്കുന്നതിനെതിരായ പ്രധാന ഘടകം ഏത്?', '["ജീവനക്കാരുടെ ശമ്പളം കുറയുന്നു എന്നത് മാത്രം","വിരമിക്കൽ ആനുകൂല്യം മുൻകൂട്ടി ഉറപ്പില്ലാത്തതും നിക്ഷേപ പ്രകടനവുമായി ബന്ധപ്പെട്ടതുമാണ്","ജീവനക്കാർക്ക് GPF ലഭിക്കില്ല എന്നത് മാത്രം","വിരമിക്കൽ പ്രായം കുറയുന്നു"]'::jsonb, 1, 'easy', 'Political', 'NPS-ൽ പെൻഷൻ തുക മുൻകൂട്ടി ഉറപ്പില്ല; അത് പെൻഷൻ ഫണ്ട് നിക്ഷേപങ്ങളുടെ വിപണി പ്രകടനത്തെ ആശ്രയിച്ചിരിക്കുന്നു.', 'nps-risk', false),
('2002 ജനുവരിയിൽ കേരളത്തിലെ എ.കെ. ആന്റണി സർക്കാർ പ്രഖ്യാപിച്ച സാമ്പത്തിക നടപടികളിൽ ഉൾപ്പെട്ടത് ഏത്?', '["എല്ലാ ജീവനക്കാർക്കും ശമ്പളവർധന","പുതിയ നിയമനങ്ങൾക്ക് Contributory Pension Scheme കൊണ്ടുവരൽ","OPS വിപുലീകരിക്കൽ","പെൻഷൻ പ്രായം 60 ആക്കൽ"]'::jsonb, 1, 'medium', 'Political', 'പുതുതായി നിയമിക്കപ്പെടുന്നവർക്ക് പങ്കാളിത്ത (contributory) പെൻഷൻ കൊണ്ടുവരാനുള്ള നിർദ്ദേശം 2002-ലെ സാമ്പത്തിക നടപടികളിൽ ഉൾപ്പെട്ടിരുന്നു.', 'kerala-2002', false),
('2002-ലെ ആന്റണി സർക്കാരിന്റെ സാമ്പത്തിക നടപടികൾക്കെതിരെ നടന്ന ചരിത്രപ്രധാനമായ ജീവനക്കാരുടെ സമരം എത്ര ദിവസം നീണ്ടു?', '["16 ദിവസം","21 ദിവസം","32 ദിവസം","45 ദിവസം"]'::jsonb, 2, 'medium', 'Political', '2002-ൽ ജീവനക്കാരും അധ്യാപകരും നടത്തിയ പണിമുടക്ക് 32 ദിവസം നീണ്ടു.', 'kerala-2002', false),
('കേരളത്തിൽ NPS ഔദ്യോഗികമായി നടപ്പാക്കുന്നതിനുള്ള പ്രധാന ഉത്തരവ് ഏത്?', '["GO(P) 56/2002/Fin","GO(P) 172/2018/Fin","GO(P) 20/2013/Fin","GO(P) 45/2016/Fin"]'::jsonb, 2, 'hard', 'Political', 'ധനകാര്യ വകുപ്പിന്റെ GO(P) 20/2013/Fin ഉത്തരവ് പ്രകാരമാണ് കേരളത്തിൽ പങ്കാളിത്ത പെൻഷൻ (NPS) നടപ്പാക്കിയത്.', 'kerala-go', false),
('കേരളത്തിൽ NPS പ്രാബല്യത്തിൽ വന്നത് ഏത് തീയതി മുതൽ?', '["01-01-2013","01-04-2013","01-07-2013","01-01-2014"]'::jsonb, 1, 'easy', 'Political', '01-04-2013-നോ അതിനുശേഷമോ സർവീസിൽ പ്രവേശിച്ചവർക്കാണ് കേരളത്തിൽ NPS ബാധകം.', 'kerala-date', false),
('2013-ൽ കേരളത്തിൽ NPS നടപ്പാക്കിയ സർക്കാർ ഏത്?', '["വി.എസ്. സർക്കാർ","ഒന്നാം പിണറായി സർക്കാർ","ഉമ്മൻചാണ്ടി നേതൃത്വം നൽകിയ UDF സർക്കാർ","രണ്ടാം പിണറായി സർക്കാർ"]'::jsonb, 2, 'easy', 'Political', 'ഉമ്മൻചാണ്ടി മുഖ്യമന്ത്രിയായിരുന്ന UDF സർക്കാരാണ് 2013-ൽ പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കിയത്.', 'kerala-2013', false),
('2013-ലെ NPS-ന് എതിരെയുള്ള ജീവനക്കാരുടെ പണിമുടക്ക് എത്ര ദിവസം നീണ്ടു?', '["3 ദിവസം","6 ദിവസം","10 ദിവസം","15 ദിവസം"]'::jsonb, 1, 'medium', 'Political', 'പങ്കാളിത്ത പെൻഷനെതിരെ 2013-ൽ ആരംഭിച്ച അനിശ്ചിതകാല പണിമുടക്ക് ആറു ദിവസം നീണ്ടു.', 'kerala-2013', false),
('കേരളത്തിൽ 2013-ലെ ജീവനക്കാരുടെ ആറുദിവസത്തെ സമരം ഏത് സർക്കാരിന്റെ തീരുമാനത്തിനെതിരെയായിരുന്നു?', '["LDF സർക്കാർ","കേന്ദ്ര സർക്കാർ","കേരളത്തിലെ UDF സർക്കാർ","NDA സർക്കാർ"]'::jsonb, 2, 'easy', 'Political', 'പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കാനുള്ള കേരളത്തിലെ UDF സർക്കാരിന്റെ തീരുമാനത്തിനെതിരെയായിരുന്നു സമരം.', 'kerala-2013', false),
('കേരളത്തിൽ 2002-ൽ contributory pension പ്രഖ്യാപിച്ച സർക്കാർ ഏത്?', '["LDF","UDF – എ.കെ. ആന്റണി സർക്കാർ","NDA","ഒന്നാം പിണറായി സർക്കാർ"]'::jsonb, 1, 'medium', 'Political', 'എ.കെ. ആന്റണി നേതൃത്വം നൽകിയ UDF സർക്കാരാണ് 2002-ൽ പങ്കാളിത്ത പെൻഷൻ നിർദ്ദേശം കൊണ്ടുവന്നത്.', 'kerala-2002', false),
('NPS-ൽ ജീവനക്കാർക്കുണ്ടായ “insecurity” പരിഹരിക്കാൻ രണ്ടാം പിണറായി സർക്കാർ മുന്നോട്ടുവച്ച സമീപനം എന്താണ്?', '["NPS കൂടുതൽ വിപണിനിർഭരമാക്കുക","Assured Pension / സുരക്ഷിത പെൻഷൻ സംവിധാനത്തിലേക്ക് പരിഷ്കരിക്കുക","പെൻഷൻ അവസാനിപ്പിക്കുക","ജീവനക്കാരുടെ സംഭാവന ഇരട്ടിയാക്കുക"]'::jsonb, 1, 'medium', 'Political', 'വിപണിയെ മാത്രം ആശ്രയിക്കാത്ത, ഉറപ്പുള്ള (Assured) പെൻഷൻ സംവിധാനത്തിലേക്കുള്ള പരിഷ്കരണമാണ് മുന്നോട്ടുവച്ചത്.', 'assured-pension', false),
('2013-ലെ NPS വിരുദ്ധ സമരത്തിൽ FSETO-യുമായി ബന്ധപ്പെട്ട ജീവനക്കാരുടെയും അധ്യാപകരുടെയും സംഘടനകൾ സ്വീകരിച്ച നിലപാട് എന്തായിരുന്നു?', '["NPS അനുകൂലിച്ചു","NPS നടപ്പാക്കുന്നതിനെ എതിർത്ത് അനിശ്ചിതകാല സമരം നടത്തി","സമരത്തിൽ നിന്ന് വിട്ടുനിന്നു","സ്വകാര്യ പെൻഷൻ ആവശ്യപ്പെട്ടു"]'::jsonb, 1, 'easy', 'Political', 'FSETO-യിലെ സംഘടനകൾ പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കുന്നതിനെ എതിർത്ത് അനിശ്ചിതകാല പണിമുടക്ക് നടത്തി.', 'fseto-stance', false),
('“NPS → OPS” എന്ന മുദ്രാവാക്യത്തിന്റെ അടിസ്ഥാന ആവശ്യം എന്താണ്?', '["സ്വകാര്യ പെൻഷൻ","ഉറപ്പുള്ള പഴയ പെൻഷൻ സംവിധാനത്തിലേക്കുള്ള മടക്കം","ജീവനക്കാരുടെ ശമ്പളം കുറയ്ക്കൽ","വിരമിക്കൽ പ്രായം കുറയ്ക്കൽ"]'::jsonb, 1, 'easy', 'Political', 'NPS ഉപേക്ഷിച്ച് ഉറപ്പുള്ള പഴയ പെൻഷൻ പദ്ധതിയിലേക്ക് (OPS) മടങ്ങണമെന്നതാണ് ആവശ്യം.', 'restore-ops', false),
('NPS-ൽ ചേരാത്ത മൂന്ന് സംസ്ഥാനങ്ങൾ എന്ന നിലയിൽ PFRDA-യുടെ 2012–13 റിപ്പോർട്ടിൽ പരാമർശിക്കപ്പെട്ടത് ഏതൊക്കെ?', '["കേരളം, തമിഴ്നാട്, പശ്ചിമബംഗാൾ","കേരളം, പശ്ചിമബംഗാൾ, ത്രിപുര","കേരളം, പഞ്ചാബ്, ത്രിപുര","പശ്ചിമബംഗാൾ, ഒഡീഷ, ത്രിപുര"]'::jsonb, 1, 'hard', 'Political', 'PFRDA-യുടെ 2012–13 റിപ്പോർട്ടിൽ കേരളം, പശ്ചിമബംഗാൾ, ത്രിപുര എന്നിവയെ NPS-ൽ ചേരാത്ത സംസ്ഥാനങ്ങളായി പരാമർശിച്ചു.', 'non-nps-states', false),
('NPS-നെ OPS-ൽ നിന്ന് വേർതിരിക്കുന്ന പ്രധാന സവിശേഷത ഏത്?', '["OPS – Defined Contribution; NPS – Defined Benefit","രണ്ടും Defined Benefit","OPS – Defined Benefit; NPS – Defined Contribution","രണ്ടും Defined Contribution"]'::jsonb, 2, 'medium', 'Political', 'OPS-ൽ പെൻഷൻ (ആനുകൂല്യം) മുൻകൂട്ടി നിശ്ചയിക്കപ്പെട്ടതാണ്; NPS-ൽ നിശ്ചയിക്കപ്പെടുന്നത് വിഹിതം (contribution) മാത്രം.', 'db-dc', false),
('കേരളത്തിൽ NPS നടപ്പാക്കുന്നതിനെതിരെ കേരള എൻ.ജി.ഒ യൂണിയൻ പ്രധാനമായും ഉന്നയിച്ച ആവശ്യം എന്തായിരുന്നു?', '["NPS വിപുലീകരിക്കുക","പഴയ പെൻഷൻ സംവിധാനം സംരക്ഷിക്കുക/പുനഃസ്ഥാപിക്കുക","വിരമിക്കൽ പ്രായം കുറയ്ക്കുക","ശമ്പളം കുറയ്ക്കുക"]'::jsonb, 1, 'easy', 'Political', 'പഴയ (സ്റ്റാറ്റ്യൂട്ടറി) പെൻഷൻ സംരക്ഷിക്കുകയും പുനഃസ്ഥാപിക്കുകയും ചെയ്യണമെന്നതായിരുന്നു പ്രധാന ആവശ്യം.', 'restore-ops', false),
('പഴയ പെൻഷൻ പദ്ധതി നിലനിർത്തണമെന്ന വാദത്തിന്റെ അടിസ്ഥാന ആശയം ഏത്?', '["പെൻഷൻ വിപണിയെ ആശ്രയിക്കണം","വിരമിക്കുമ്പോഴുള്ള വരുമാനത്തിൽ സർക്കാർ ഉറപ്പ് വേണം","ജീവനക്കാർക്ക് സംഭാവന നൽകേണ്ടതില്ല എന്നത് മാത്രം","ഓഹരി വിപണിയിൽ നിക്ഷേപം വർധിപ്പിക്കുക"]'::jsonb, 1, 'easy', 'Political', 'വിരമിച്ച ശേഷമുള്ള വരുമാനത്തിന് സർക്കാർ ഉറപ്പ് നൽകണം എന്നതാണ് പഴയ പെൻഷന്റെ അടിസ്ഥാന ആശയം.', 'ops-principle', false),
('NPS-ൽ നിന്ന് വിട്ടുനിന്ന കേരളം, പശ്ചിമബംഗാൾ, ത്രിപുര എന്നീ സംസ്ഥാനങ്ങളുടെ സമീപനത്തെക്കുറിച്ച് താഴെപ്പറയുന്നതിൽ ഏറ്റവും ഉചിതമായ വിശദീകരണം ഏത്?', '["എല്ലാ സംസ്ഥാനങ്ങളും ഒരേ കാരണത്താലാണ് വിട്ടുനിന്നത്","കേന്ദ്രസർക്കാർ അവരെ NPS-ൽ ചേരാൻ അനുവദിച്ചില്ല","സംസ്ഥാനങ്ങളുടെ സ്വന്തം പെൻഷൻ നയം, ധനകാര്യ സമീപനം, രാഷ്ട്രീയ നയം എന്നിവ അനുസരിച്ച് തീരുമാനങ്ങൾ വ്യത്യസ്തമായിരുന്നു","NPS സംസ്ഥാനങ്ങൾക്ക് ബാധകമല്ലായിരുന്നു"]'::jsonb, 2, 'hard', 'Political', 'NPS-ൽ ചേരണോ എന്നത് ഓരോ സംസ്ഥാനത്തിന്റെയും തീരുമാനമായിരുന്നു; പെൻഷൻ നയം, ധനസ്ഥിതി, രാഷ്ട്രീയ നിലപാട് എന്നിവയനുസരിച്ച് തീരുമാനങ്ങൾ വ്യത്യസ്തമായി.', 'non-nps-states', false),
('NPS-ന്റെ നിയന്ത്രണവുമായി ബന്ധപ്പെട്ട പ്രധാന സ്ഥാപനമേത്?', '["RBI","SEBI","PFRDA","UPSC"]'::jsonb, 2, 'easy', 'Political', 'NPS-ന്റെ നിയന്ത്രണ അതോറിറ്റി PFRDA (Pension Fund Regulatory and Development Authority) ആണ്.', 'pfrda', false),
('PFRDA-യുടെ പൂർണ്ണരൂപം ഏത്?', '["Pension Fund Regulatory and Development Authority","Provident Fund Regulatory and Development Authority","Public Finance Regulation and Development Authority","Pension Fund Revenue and Deposit Authority"]'::jsonb, 0, 'easy', 'Political', 'Pension Fund Regulatory and Development Authority – NPS നിയന്ത്രിക്കുന്ന സ്ഥാപനം.', 'pfrda', false),
('PFRDA-ക്ക് നിയമപരമായ (statutory) പദവി നൽകിയ PFRDA നിയമം പാസായ വർഷം?', '["2003","2009","2013","2016"]'::jsonb, 2, 'medium', 'Political', 'PFRDA Act, 2013 പാർലമെന്റ് പാസാക്കിയതോടെ PFRDA നിയമപരമായ അതോറിറ്റിയായി.', 'pfrda-act', false),
('NPS-ൽ ഓരോ അംഗത്തിനും നൽകുന്ന സ്ഥിര അക്കൗണ്ട് നമ്പറായ PRAN-ന്റെ പൂർണ്ണരൂപം?', '["Permanent Retirement Account Number","Pension Registration Account Number","Provident Retirement Allotment Number","Permanent Remittance Account Number"]'::jsonb, 0, 'easy', 'Political', 'PRAN – Permanent Retirement Account Number. ജോലി മാറിയാലും ഇതേ നമ്പർ തുടരും.', 'pran', false),
('NPS-ൽ വിരമിക്കുമ്പോൾ മൊത്തം നിക്ഷേപത്തുകയുടെ (corpus) കുറഞ്ഞത് എത്ര ശതമാനം annuity വാങ്ങാൻ ഉപയോഗിക്കണം?', '["20%","40%","60%","100%"]'::jsonb, 1, 'medium', 'Political', 'കുറഞ്ഞത് 40% annuity വാങ്ങാൻ നിർബന്ധം; പരമാവധി 60% ഒറ്റത്തവണയായി പിൻവലിക്കാം.', 'annuity', false),
('NPS-ൽ വിരമിച്ച ശേഷം ലഭിക്കുന്ന പ്രതിമാസ പെൻഷൻ പ്രധാനമായും എന്തിനെ ആശ്രയിച്ചിരിക്കുന്നു?', '["അവസാന ശമ്പളത്തിന്റെ 50%","വാങ്ങുന്ന annuity തുകയും ആ സമയത്തെ annuity നിരക്കും","സർവീസ് കാലയളവ് മാത്രം","നിലവിലെ ഡി.എ. നിരക്ക്"]'::jsonb, 1, 'medium', 'Political', 'NPS പെൻഷൻ എന്നത് corpus ഉപയോഗിച്ച് വാങ്ങുന്ന annuity ആണ്; അതിന്റെ തുക annuity നിരക്കിനെ ആശ്രയിക്കുന്നു.', 'annuity', false),
('NPS-ൽ ജീവനക്കാരന്റെ പ്രതിമാസ വിഹിതം (contribution) എത്ര?', '["അടിസ്ഥാന ശമ്പളത്തിന്റെ 5%","അടിസ്ഥാന ശമ്പളം + ഡി.എ.യുടെ 10%","അടിസ്ഥാന ശമ്പളത്തിന്റെ 20%","ജീവനക്കാരൻ വിഹിതം നൽകേണ്ടതില്ല"]'::jsonb, 1, 'easy', 'Political', 'ജീവനക്കാരൻ അടിസ്ഥാന ശമ്പളം + ഡി.എ.യുടെ 10% ഓരോ മാസവും NPS-ലേക്ക് അടയ്ക്കണം.', 'contribution', false),
('''Defined Benefit'' പെൻഷൻ പദ്ധതി എന്നാൽ എന്ത്?', '["നിക്ഷേപ ലാഭത്തിനനുസരിച്ച് തുക മാറുന്ന പെൻഷൻ","വിരമിക്കുമ്പോൾ ലഭിക്കുന്ന പെൻഷൻ നിയമപ്രകാരം മുൻകൂട്ടി നിശ്ചയിക്കപ്പെട്ടത്","ജീവനക്കാരന്റെ വിഹിതം മാത്രം തിരിച്ചുനൽകുന്ന പദ്ധതി","ഒറ്റത്തവണ മാത്രം തുക ലഭിക്കുന്ന പദ്ധതി"]'::jsonb, 1, 'medium', 'Political', 'Defined Benefit പദ്ധതിയിൽ (ഉദാ: OPS) പെൻഷൻ എത്രയെന്ന് സർവീസും ശമ്പളവും അടിസ്ഥാനമാക്കി നിയമം തന്നെ നിശ്ചയിക്കുന്നു.', 'db-dc', false),
('''Defined Contribution'' പെൻഷൻ പദ്ധതിയിൽ മുൻകൂട്ടി നിശ്ചയിക്കപ്പെട്ടിട്ടുള്ളത് എന്താണ്?', '["വിരമിക്കുമ്പോഴുള്ള പെൻഷൻ തുക","ഓരോ മാസവും അടയ്ക്കേണ്ട വിഹിതം","ഡി.എ. വർധന","കുടുംബ പെൻഷൻ തുക"]'::jsonb, 1, 'medium', 'Political', 'Defined Contribution പദ്ധതിയിൽ (ഉദാ: NPS) വിഹിതം മാത്രമാണ് നിശ്ചിതം; പെൻഷൻ തുക നിക്ഷേപ ഫലത്തെ ആശ്രയിക്കുന്നു.', 'db-dc', false),
('പഴയ പെൻഷൻ പദ്ധതിയിൽ വിലക്കയറ്റത്തിൽ നിന്ന് പെൻഷൻകാരെ സംരക്ഷിക്കുന്നത് എന്ത്?', '["ഓഹരി വിപണി ലാഭം","ക്ഷാമാശ്വാസം (Dearness Relief) വർധനവ്","annuity നിരക്ക്","ബോണസ്"]'::jsonb, 1, 'easy', 'Political', 'പഴയ പെൻഷനിൽ വിലക്കയറ്റത്തിനനുസരിച്ച് ക്ഷാമാശ്വാസം (DR) വർധിക്കും; NPS annuity-ക്ക് ഇത്തരം വർധനവ് ഇല്ല.', 'dearness-relief', false),
('പഴയ പെൻഷൻ പദ്ധതിയിൽ പൂർണ്ണ സർവീസുള്ള ജീവനക്കാരന് ലഭിക്കുന്ന പെൻഷൻ ഏകദേശം എത്ര?', '["അടിസ്ഥാന ശമ്പളത്തിന്റെ 25%","അടിസ്ഥാന ശമ്പളത്തിന്റെ 50%","അടിസ്ഥാന ശമ്പളത്തിന്റെ 75%","അടിസ്ഥാന ശമ്പളത്തിന്റെ 100%"]'::jsonb, 1, 'medium', 'Political', 'പൂർണ്ണ യോഗ്യതാ സർവീസുള്ളവർക്ക് (ശരാശരി) അടിസ്ഥാന ശമ്പളത്തിന്റെ പകുതി പെൻഷനായി ലഭിക്കും; ഒപ്പം ക്ഷാമാശ്വാസവും.', 'ops-amount', false),
('''പെൻഷൻ ഔദാര്യമല്ല, അവകാശമാണ്'' എന്ന് വ്യക്തമാക്കിയ സുപ്രീംകോടതി വിധി ഏത്?', '["കേശവാനന്ദ ഭാരതി കേസ്","ഡി.എസ്. നകാര കേസ്","ഇന്ദിരാ സാഹ്നി കേസ്","മിനർവ മിൽസ് കേസ്"]'::jsonb, 1, 'medium', 'Political', 'ഡി.എസ്. നകാര v. യൂണിയൻ ഓഫ് ഇന്ത്യ (1982) കേസിൽ പെൻഷൻ ഔദാര്യമല്ല, അവകാശമാണെന്ന് സുപ്രീംകോടതി വ്യക്തമാക്കി.', 'nakara', false),
('ഡി.എസ്. നകാര v. യൂണിയൻ ഓഫ് ഇന്ത്യ കേസിൽ സുപ്രീംകോടതി വിധി പുറപ്പെടുവിച്ച വർഷം?', '["1975","1982","1991","2004"]'::jsonb, 1, 'hard', 'Political', '1982 ഡിസംബർ 17-നാണ് വിധി; ആ ദിവസം പെൻഷനേഴ്സ് ദിനമായി ആചരിക്കുന്നു.', 'nakara', false),
('പെൻഷനേഴ്സ് ദിനം ആചരിക്കുന്നത് എന്ന്?', '["മേയ് 1","ഡിസംബർ 17","ഒക്ടോബർ 1","ജനുവരി 26"]'::jsonb, 1, 'medium', 'Political', 'ഡി.എസ്. നകാര കേസിലെ സുപ്രീംകോടതി വിധിയുടെ (1982 ഡിസംബർ 17) ഓർമ്മയ്ക്കായി ഡിസംബർ 17 പെൻഷനേഴ്സ് ദിനമായി ആചരിക്കുന്നു.', 'nakara', false),
('NPS-ലുള്ള കേന്ദ്ര ജീവനക്കാർക്ക് ഓപ്ഷനായി 2024-ൽ കേന്ദ്രസർക്കാർ പ്രഖ്യാപിച്ച പെൻഷൻ പദ്ധതി?', '["Unified Pension Scheme (UPS)","Atal Pension Yojana","Universal Retirement Scheme","Assured Gratuity Scheme"]'::jsonb, 0, 'medium', 'Political', '2024 ഓഗസ്റ്റിൽ പ്രഖ്യാപിച്ച Unified Pension Scheme (UPS) NPS-ലുള്ള കേന്ദ്ര ജീവനക്കാർക്കുള്ള ഓപ്ഷനാണ്.', 'ups', false),
('കേന്ദ്രത്തിന്റെ Unified Pension Scheme (UPS) പ്രാബല്യത്തിൽ വന്ന തീയതി?', '["01-01-2025","01-04-2025","01-08-2024","01-04-2026"]'::jsonb, 1, 'hard', 'Political', 'UPS 2025 ഏപ്രിൽ 1 മുതൽ പ്രാബല്യത്തിൽ വന്നു.', 'ups', false),
('Unified Pension Scheme (UPS) പ്രകാരം 25 വർഷം സർവീസുള്ളവർക്ക് ഉറപ്പാക്കുന്ന പെൻഷൻ?', '["അവസാന 12 മാസത്തെ ശരാശരി അടിസ്ഥാന ശമ്പളത്തിന്റെ 50%","അവസാന ശമ്പളത്തിന്റെ 25%","അവസാന ശമ്പളത്തിന്റെ 60%","അവസാന ശമ്പളത്തിന്റെ 100%"]'::jsonb, 0, 'hard', 'Political', 'UPS-ൽ 25 വർഷം സർവീസുള്ളവർക്ക് അവസാന 12 മാസത്തെ ശരാശരി അടിസ്ഥാന ശമ്പളത്തിന്റെ 50% ഉറപ്പാക്കുന്നു.', 'ups', false),
('NPS ഉപേക്ഷിച്ച് പഴയ പെൻഷനിലേക്ക് മടങ്ങുമെന്ന് 2022-ലെ ബജറ്റിൽ പ്രഖ്യാപിച്ച സംസ്ഥാനം?', '["ഗുജറാത്ത്","രാജസ്ഥാൻ","ഉത്തർപ്രദേശ്","മഹാരാഷ്ട്ര"]'::jsonb, 1, 'medium', 'Political', '2022-ലെ ബജറ്റിൽ രാജസ്ഥാൻ പഴയ പെൻഷൻ പുനഃസ്ഥാപിക്കുമെന്ന് പ്രഖ്യാപിച്ചു; പിന്നീട് മറ്റ് ചില സംസ്ഥാനങ്ങളും ഇതേ വഴി സ്വീകരിച്ചു.', 'rajasthan-ops', false),
('NPS-ലെ നിർബന്ധിത പെൻഷൻ അക്കൗണ്ട് ഏത്?', '["Tier I","Tier II","Tier III","GPF അക്കൗണ്ട്"]'::jsonb, 0, 'medium', 'Political', 'Tier I നിർബന്ധിത പെൻഷൻ അക്കൗണ്ടാണ്; Tier II സ്വമേധയാ ഉള്ള സമ്പാദ്യ അക്കൗണ്ടും.', 'tiers', false),
('NPS-ലെ Tier II അക്കൗണ്ടിന്റെ സവിശേഷത എന്ത്?', '["നിർബന്ധിത പെൻഷൻ അക്കൗണ്ട്","സ്വമേധയാ ഉള്ള സമ്പാദ്യ അക്കൗണ്ട്; തുക ആവശ്യാനുസരണം പിൻവലിക്കാം","സർക്കാർ വിഹിതം ഇരട്ടിയാകുന്ന അക്കൗണ്ട്","വിരമിച്ചവർക്ക് മാത്രമുള്ള അക്കൗണ്ട്"]'::jsonb, 1, 'medium', 'Political', 'Tier II സ്വമേധയാ ഉള്ളതാണ്; അതിൽ നിന്ന് ആവശ്യാനുസരണം തുക പിൻവലിക്കാം.', 'tiers', false),
('കേരളത്തിൽ ഏത് ജീവനക്കാരാണ് പങ്കാളിത്ത പെൻഷന്റെ (NPS) പരിധിയിൽ വരുന്നത്?', '["എല്ലാ ജീവനക്കാരും","01-04-2013-നോ അതിനുശേഷമോ സർവീസിൽ പ്രവേശിച്ചവർ","2004-ന് ശേഷം നിയമിതരായവർ","ഗസറ്റഡ് ഉദ്യോഗസ്ഥർ മാത്രം"]'::jsonb, 1, 'easy', 'Political', '01-04-2013-നോ അതിനുശേഷമോ സർവീസിൽ പ്രവേശിച്ചവർ പങ്കാളിത്ത പെൻഷനിലാണ്; അതിനു മുമ്പുള്ളവർ പഴയ പെൻഷനിൽ തുടരുന്നു.', 'kerala-date', false),
('കേരളത്തിൽ NPS സാധാരണയായി ഏത് പേരിലാണ് അറിയപ്പെടുന്നത്?', '["പങ്കാളിത്ത പെൻഷൻ","ക്ഷേമ പെൻഷൻ","കുടുംബ പെൻഷൻ","സ്റ്റാറ്റ്യൂട്ടറി പെൻഷൻ"]'::jsonb, 0, 'easy', 'Political', 'ജീവനക്കാരനും സർക്കാരും വിഹിതം അടയ്ക്കുന്നതിനാൽ NPS കേരളത്തിൽ ''പങ്കാളിത്ത പെൻഷൻ'' എന്നറിയപ്പെടുന്നു.', 'kerala-name', false),
('FSETO-യുടെ പൂർണ്ണരൂപം ഏത്?', '["Federation of State Employees'' and Teachers'' Organisations","Forum of Service Employees and Trade Organisations","Federation of State Education and Training Officers","Front of Secretariat Employees and Teachers'' Organisations"]'::jsonb, 0, 'medium', 'Political', 'FSETO – Federation of State Employees'' and Teachers'' Organisations; കേരളത്തിലെ ജീവനക്കാരുടെയും അധ്യാപകരുടെയും സംഘടനകളുടെ ഫെഡറേഷൻ.', 'fseto', false),
('കേരള എൻ.ജി.ഒ യൂണിയൻ ജീവനക്കാരുടെയും അധ്യാപകരുടെയും ഏത് കൂട്ടായ്മയിലെ അംഗസംഘടനയാണ്?', '["FSETO","SEBI","PFRDA","NSDL"]'::jsonb, 0, 'easy', 'Political', 'കേരള എൻ.ജി.ഒ യൂണിയൻ FSETO-യിലെ അംഗസംഘടനയാണ്.', 'fseto', false),
('NPS നടപ്പാക്കുന്നതിനുള്ള കേന്ദ്ര വിജ്ഞാപനം (2003 ഡിസംബർ) പുറപ്പെടുവിക്കുമ്പോൾ പ്രധാനമന്ത്രി ആരായിരുന്നു?', '["മൻമോഹൻ സിങ്","അടൽ ബിഹാരി വാജ്പേയി","പി.വി. നരസിംഹ റാവു","ഐ.കെ. ഗുജ്റാൾ"]'::jsonb, 1, 'easy', 'Political', 'അടൽ ബിഹാരി വാജ്പേയി പ്രധാനമന്ത്രിയായിരുന്ന NDA സർക്കാരാണ് NPS വിജ്ഞാപനം ചെയ്തത്.', 'central-govt', false),
('കേന്ദ്രസർക്കാർ NPS നിർബന്ധമാക്കിയപ്പോൾ അതിൽ നിന്ന് ഒഴിവാക്കപ്പെട്ട വിഭാഗം ഏത്?', '["സായുധ സേന (Armed Forces)","റെയിൽവേ","തപാൽ വകുപ്പ്","ആദായനികുതി വകുപ്പ്"]'::jsonb, 0, 'medium', 'Political', '2004 മുതൽ NPS കേന്ദ്ര സിവിൽ സർവീസിന് നിർബന്ധമാക്കിയെങ്കിലും സായുധ സേനയെ ഒഴിവാക്കി.', 'central-scope', false),
('കേരളത്തിൽ പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കിയ 2013-ൽ മുഖ്യമന്ത്രി ആരായിരുന്നു?', '["വി.എസ്. അച്യുതാനന്ദൻ","ഉമ്മൻ ചാണ്ടി","എ.കെ. ആന്റണി","പിണറായി വിജയൻ"]'::jsonb, 1, 'easy', 'Political', '2013-ൽ ഉമ്മൻ ചാണ്ടിയായിരുന്നു മുഖ്യമന്ത്രി.', 'kerala-2013', false),
('2002-ൽ കേരളത്തിൽ ജീവനക്കാരുടെ 32 ദിവസത്തെ പണിമുടക്ക് നടക്കുമ്പോൾ മുഖ്യമന്ത്രി ആരായിരുന്നു?', '["ഇ.കെ. നായനാർ","എ.കെ. ആന്റണി","ഉമ്മൻ ചാണ്ടി","കെ. കരുണാകരൻ"]'::jsonb, 1, 'easy', 'Political', '2002-ൽ എ.കെ. ആന്റണിയായിരുന്നു മുഖ്യമന്ത്രി.', 'kerala-2002', false),
('കേരളത്തിലെ ജീവനക്കാരും അധ്യാപകരും 32 ദിവസം നീണ്ട പണിമുടക്ക് നടത്തിയ വർഷം?', '["1997","2002","2006","2013"]'::jsonb, 1, 'medium', 'Political', 'ആന്റണി സർക്കാരിന്റെ സാമ്പത്തിക നടപടികൾക്കെതിരെ 2002-ലായിരുന്നു 32 ദിവസത്തെ പണിമുടക്ക്.', 'kerala-2002', false),
('കേരളത്തിൽ പങ്കാളിത്ത പെൻഷനെതിരെ ജീവനക്കാരും അധ്യാപകരും അനിശ്ചിതകാല പണിമുടക്ക് നടത്തിയ വർഷം?', '["2002","2010","2013","2016"]'::jsonb, 2, 'easy', 'Political', 'പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കുന്നതിനെതിരെ 2013-ലായിരുന്നു അനിശ്ചിതകാല പണിമുടക്ക്.', 'kerala-2013', false),
('കേരളത്തിൽ പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കിക്കൊണ്ടുള്ള ഉത്തരവ് പുറപ്പെടുവിച്ച വകുപ്പ് ഏത്?', '["ധനകാര്യ വകുപ്പ്","പൊതുഭരണ വകുപ്പ്","നിയമ വകുപ്പ്","തൊഴിൽ വകുപ്പ്"]'::jsonb, 0, 'medium', 'Political', 'ധനകാര്യ വകുപ്പിന്റെ ഉത്തരവിലൂടെയാണ് (GO(P) 20/2013/Fin) പങ്കാളിത്ത പെൻഷൻ നടപ്പാക്കിയത്.', 'kerala-go', false),
('NPS സ്വകാര്യ മേഖല ഉൾപ്പെടെ എല്ലാ ഇന്ത്യൻ പൗരന്മാർക്കും തുറന്നുകൊടുത്ത വർഷം?', '["2004","2009","2013","2015"]'::jsonb, 1, 'hard', 'Political', '2009 മേയ് 1 മുതൽ NPS എല്ലാ പൗരന്മാർക്കും ലഭ്യമാക്കി.', 'all-citizens', false),
('NPS-ൽ വിരമിക്കൽ ആനുകൂല്യം നിശ്ചയിക്കുന്നതിൽ നിർണ്ണായക സ്വാധീനമുള്ളത് എന്ത്?', '["സർക്കാർ ഉത്തരവ് മാത്രം","പെൻഷൻ ഫണ്ട് നിക്ഷേപങ്ങളുടെ വിപണി പ്രകടനം","ജീവനക്കാരന്റെ തസ്തിക","ശമ്പള പരിഷ്കരണം"]'::jsonb, 1, 'medium', 'Political', 'NPS-ൽ സ്വരൂപിക്കുന്ന തുക നിക്ഷേപങ്ങളുടെ വിപണി പ്രകടനത്തെ ആശ്രയിച്ചിരിക്കുന്നു; അതിനാൽ ആനുകൂല്യം മുൻകൂട്ടി ഉറപ്പില്ല.', 'nps-risk', false),
('NPS-ൽ നിക്ഷേപ നഷ്ടത്തിന്റെ (market risk) ബാധ്യത പ്രധാനമായും ആർ വഹിക്കുന്നു?', '["ജീവനക്കാരൻ","സർക്കാർ","PFRDA","RBI"]'::jsonb, 0, 'medium', 'Political', 'Defined Contribution പദ്ധതിയായതിനാൽ വിപണിയിലെ ഏറ്റക്കുറച്ചിലുകളുടെ ഫലം ജീവനക്കാരന്റെ corpus-നെയാണ് ബാധിക്കുന്നത്.', 'nps-risk', false),
('വിരമിച്ച ശേഷം ഉറപ്പുള്ള പ്രതിമാസ പെൻഷനും ക്ഷാമാശ്വാസവും ഉറപ്പാക്കുന്ന പദ്ധതി ഏത്?', '["പഴയ (സ്റ്റാറ്റ്യൂട്ടറി) പെൻഷൻ പദ്ധതി","NPS","Atal Pension Yojana","EPF"]'::jsonb, 0, 'easy', 'Political', 'പഴയ പെൻഷൻ പദ്ധതിയിൽ നിശ്ചിത പെൻഷനും വിലക്കയറ്റത്തിനനുസരിച്ച് ക്ഷാമാശ്വാസവും ലഭിക്കും.', 'ops-principle', false),
('കേന്ദ്രത്തിന്റെ NPS നടപ്പാക്കാതെ പഴയ പെൻഷൻ തുടർന്ന സംസ്ഥാനം ഏത്?', '["പശ്ചിമബംഗാൾ","കർണാടക","ഗുജറാത്ത്","മധ്യപ്രദേശ്"]'::jsonb, 0, 'medium', 'Political', 'പശ്ചിമബംഗാൾ NPS-ൽ ചേരാതെ പഴയ പെൻഷൻ സംവിധാനം തുടർന്നു.', 'non-nps-states', false),
('NPS-ൽ സർക്കാർ ജീവനക്കാരുടെ പെൻഷൻ ഫണ്ട് കൈകാര്യം ചെയ്യുന്ന പെൻഷൻ ഫണ്ട് മാനേജർമാരിൽ ഉൾപ്പെടുന്നത്?', '["SBI, LIC, UTI പെൻഷൻ ഫണ്ടുകൾ","RBI, NABARD, SIDBI","KSFE, KSEB, KSRTC","ISRO, DRDO, BHEL"]'::jsonb, 0, 'medium', 'Political', 'സർക്കാർ മേഖലയിലെ NPS ഫണ്ട് SBI, LIC, UTI എന്നിവയുടെ പെൻഷൻ ഫണ്ടുകളാണ് കൈകാര്യം ചെയ്യുന്നത്.', 'fund-managers', false),
('''Assured Pension'' (ഉറപ്പുള്ള പെൻഷൻ) എന്ന ആശയത്തിന്റെ പ്രധാന സവിശേഷത?', '["വിപണിയെ മാത്രം ആശ്രയിക്കാതെ നിശ്ചിത പെൻഷൻ ഉറപ്പാക്കുന്നു","ജീവനക്കാരുടെ വിഹിതം പൂർണ്ണമായും ഓഹരിയിൽ നിക്ഷേപിക്കുന്നു","പെൻഷൻ ഒറ്റത്തവണയായി മാത്രം നൽകുന്നു","വിരമിക്കൽ പ്രായം കൂട്ടുന്നു"]'::jsonb, 0, 'easy', 'Political', 'വിരമിച്ച ശേഷം ഒരു നിശ്ചിത പെൻഷൻ തുക ഉറപ്പാക്കുന്നു എന്നതാണ് Assured Pension-ന്റെ കാതൽ.', 'assured-pension', false),
('കേന്ദ്രസർക്കാർ സർവീസിൽ ഏത് വർഷം മുതൽ നിയമിതരായവർക്കാണ് NPS ബാധകമായത്?', '["2001","2004","2009","2013"]'::jsonb, 1, 'easy', 'Political', '2004 ജനുവരി 1 മുതൽ കേന്ദ്ര സർവീസിൽ പ്രവേശിച്ചവർ NPS-ലാണ്.', 'central-date', false),
('PFRDA ആദ്യമായി (ഇടക്കാല സംവിധാനമായി) രൂപീകരിച്ച വർഷം?', '["1999","2003","2009","2013"]'::jsonb, 1, 'hard', 'Political', '2003-ൽ സർക്കാർ പ്രമേയത്തിലൂടെ ഇടക്കാല PFRDA രൂപീകരിച്ചു; 2013-ലെ നിയമത്തോടെ നിയമപരമായ പദവി ലഭിച്ചു.', 'pfrda-act', false),
('NPS-ൽ അംഗങ്ങളുടെ അക്കൗണ്ട് രേഖകൾ സൂക്ഷിക്കുന്ന സ്ഥാപനം അറിയപ്പെടുന്നത്?', '["Central Recordkeeping Agency (CRA)","Central Pension Accounting Office","Accountant General","District Treasury"]'::jsonb, 0, 'hard', 'Political', 'NPS അക്കൗണ്ട് രേഖകൾ Central Recordkeeping Agency (CRA) ആണ് സൂക്ഷിക്കുന്നത്.', 'cra', false),
('NPS-ൽ വിരമിക്കുമ്പോൾ corpus-ന്റെ പരമാവധി എത്ര ശതമാനം ഒറ്റത്തവണയായി പിൻവലിക്കാം?', '["40%","50%","60%","100%"]'::jsonb, 2, 'hard', 'Political', 'പരമാവധി 60% ഒറ്റത്തവണയായി പിൻവലിക്കാം; ബാക്കി കുറഞ്ഞത് 40% annuity വാങ്ങാൻ ഉപയോഗിക്കണം.', 'annuity', false),
('സംസ്ഥാന ജീവനക്കാരും അധ്യാപകരും സെക്രട്ടേറിയറ്റ് വളയുന്നത് എന്ന്?', '["2026 നവംബർ 21","2026 നവംബർ 1","2026 ഡിസംബർ 6","2026 ഒക്ടോബർ 21"]'::jsonb, 0, 'easy', 'Political', '2026 നവംബർ 21 ശനിയാഴ്ചയാണ് സെക്രട്ടേറിയറ്റ് വളയൽ.', 'sv-date', true),
('2026 നവംബർ 21-ലെ സെക്രട്ടേറിയറ്റ് വളയൽ ആഴ്ചയിലെ ഏത് ദിവസമാണ്?', '["ശനി","ഞായർ","തിങ്കൾ","വെള്ളി"]'::jsonb, 0, 'medium', 'Political', '2026 നവംബർ 21 ശനിയാഴ്ചയാണ്.', 'sv-date', true),
('2026 നവംബർ 21-ന് ജീവനക്കാരും അധ്യാപകരും സംഘടിപ്പിക്കുന്ന സമരരൂപം ഏത്?', '["സെക്രട്ടേറിയറ്റ് വളയൽ","രാജ്ഭവൻ മാർച്ച്","ദേശീയ പണിമുടക്ക്","കളക്ടറേറ്റ് ധർണ്ണ"]'::jsonb, 0, 'easy', 'Political', 'അവകാശ സംരക്ഷണത്തിനായി ജീവനക്കാരും അധ്യാപകരും 2026 നവംബർ 21-ന് സെക്രട്ടേറിയറ്റ് വളയുന്നു.', 'sv-date', true),
('സെക്രട്ടേറിയറ്റ് വളയൽ നടക്കുന്നത് ഏത് നഗരത്തിൽ?', '["തിരുവനന്തപുരം","കൊച്ചി","കോഴിക്കോട്","തൃശൂർ"]'::jsonb, 0, 'easy', 'Political', 'സംസ്ഥാന ഭരണസിരാകേന്ദ്രമായ തിരുവനന്തപുരത്തെ സെക്രട്ടേറിയറ്റാണ് വളയുന്നത്.', 'sv-place', true),
('സെക്രട്ടേറിയറ്റ് വളയലിൽ എത്ര ജീവനക്കാരും അധ്യാപകരും പങ്കെടുക്കുമെന്നാണ് പ്രഖ്യാപനം?', '["കാൽലക്ഷത്തിലധികം","അയ്യായിരം","പതിനായിരം","ഒരു ലക്ഷത്തിലധികം"]'::jsonb, 0, 'easy', 'Political', 'കാൽലക്ഷത്തിലധികം (25,000-ലധികം) ജീവനക്കാരും അധ്യാപകരും സെക്രട്ടേറിയറ്റ് വളയും.', 'sv-crowd', true),
('സെക്രട്ടേറിയറ്റ് വളയലിൽ പങ്കെടുക്കുന്ന ''കാൽലക്ഷത്തിലധികം'' പേർ — ഇത് ഏകദേശം എത്ര?', '["25,000-ലധികം","2,500-ലധികം","50,000-ലധികം","75,000-ലധികം"]'::jsonb, 0, 'medium', 'Political', 'കാൽലക്ഷം = 25,000.', 'sv-crowd', true),
('സെക്രട്ടേറിയറ്റ് വളയൽ സമരം സംഘടിപ്പിക്കുന്നത് ആര്?', '["ആക്ഷൻ കൗൺസിൽ ഓഫ് സ്റ്റേറ്റ് എംപ്ലോയീസ് ആന്റ് ടീച്ചേഴ്സ്","പബ്ലിക് സർവീസ് കമ്മീഷൻ","സംസ്ഥാന ശമ്പള കമ്മീഷൻ","PFRDA"]'::jsonb, 0, 'easy', 'Political', 'ആക്ഷൻ കൗൺസിൽ ഓഫ് സ്റ്റേറ്റ് എംപ്ലോയീസ് ആന്റ് ടീച്ചേഴ്സ് ആണ് സമരം സംഘടിപ്പിക്കുന്നത്.', 'sv-organiser', true),
('ആക്ഷൻ കൗൺസിൽ ഓഫ് സ്റ്റേറ്റ് എംപ്ലോയീസ് & ടീച്ചേഴ്സിന്റെ ചെയർമാൻ ആര്?', '["ടി.കെ.എ. ഷാഫി","എം.വി. ശശിധരൻ","ചീഫ് സെക്രട്ടറി","ധനകാര്യ സെക്രട്ടറി"]'::jsonb, 0, 'medium', 'Political', 'ടി.കെ.എ. ഷാഫി ചെയർമാനും എം.വി. ശശിധരൻ ജനറൽ കൺവീനറുമാണ്.', 'sv-leaders', true),
('ആക്ഷൻ കൗൺസിൽ ഓഫ് സ്റ്റേറ്റ് എംപ്ലോയീസ് & ടീച്ചേഴ്സിന്റെ ജനറൽ കൺവീനർ ആര്?', '["എം.വി. ശശിധരൻ","ടി.കെ.എ. ഷാഫി","ചീഫ് സെക്രട്ടറി","ധനകാര്യ സെക്രട്ടറി"]'::jsonb, 0, 'medium', 'Political', 'എം.വി. ശശിധരൻ ജനറൽ കൺവീനറും ടി.കെ.എ. ഷാഫി ചെയർമാനുമാണ്.', 'sv-leaders', true),
('സെക്രട്ടേറിയറ്റ് വളയൽ സമരത്തിന്റെ സ്വഭാവം എന്ത്?', '["നിലവിൽ ലഭിക്കുന്ന അവകാശങ്ങൾ സംരക്ഷിക്കാനുള്ള പോരാട്ടം","പുതിയ ആനുകൂല്യങ്ങൾക്കായുള്ള സമരം","ഒരു തിരഞ്ഞെടുപ്പ് റാലി","ശമ്പളം കുറയ്ക്കുന്നതിനെ പിന്തുണയ്ക്കൽ"]'::jsonb, 0, 'easy', 'Political', 'ഏതെങ്കിലും പുതിയ അവകാശാനുകൂല്യങ്ങൾക്കു വേണ്ടിയല്ല; നിലവിൽ ലഭിച്ചുകൊണ്ടിരിക്കുന്നവ സംരക്ഷിച്ചു കിട്ടാനുള്ള പോരാട്ടമാണ്.', 'sv-aim', true),
('''ഏതെങ്കിലും ഒരു പുതിയ അവകാശാനുകൂല്യങ്ങൾക്ക് വേണ്ടിയല്ല സമരം'' — പിന്നെ സെക്രട്ടേറിയറ്റ് വളയൽ എന്തിനാണ്?', '["നിലവിൽ ലഭിച്ചുകൊണ്ടിരിക്കുന്നവ സംരക്ഷിച്ചു കിട്ടാൻ","വിരമിക്കൽ പ്രായം കൂട്ടാൻ","പ്രവൃത്തിദിനം കുറയ്ക്കാൻ","പുതിയ അലവൻസുകൾ നേടാൻ"]'::jsonb, 0, 'medium', 'Political', 'ലഭിച്ചുകൊണ്ടിരിക്കുന്ന അവകാശങ്ങൾ സംരക്ഷിക്കുക എന്നതാണ് സമരത്തിന്റെ ലക്ഷ്യം.', 'sv-aim', true),
('സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ആവശ്യങ്ങളിൽ ഉൾപ്പെടാത്തത് ഏത്?', '["വിരമിക്കൽ പ്രായം 62 ആക്കുക","ശമ്പള പരിഷ്കരണം ഉടൻ നടപ്പിലാക്കുക","ഏൺഡ് ലീവ് സറണ്ടർ പുനഃസ്ഥാപിക്കുക","മെഡിസെപ് അപാകതകൾ പരിഹരിക്കുക"]'::jsonb, 0, 'easy', 'Political', 'വിരമിക്കൽ പ്രായം സമരത്തിന്റെ ആവശ്യമല്ല; മറ്റു മൂന്നും ആവശ്യങ്ങളാണ്.', 'sv-demands', true),
('സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ആവശ്യങ്ങളിൽ ഉൾപ്പെടുന്നത് ഏത്?', '["ക്ഷാമബത്ത കുടിശ്ശിക അനുവദിച്ച ഉത്തരവ് ഉടൻ നടപ്പിലാക്കുക","ശമ്പളം മരവിപ്പിക്കുക","മെഡിസെപ് നിർത്തലാക്കുക","പൊതുവിദ്യാലയങ്ങൾ സ്വകാര്യവൽക്കരിക്കുക"]'::jsonb, 0, 'easy', 'Political', 'ക്ഷാമബത്ത കുടിശ്ശിക അനുവദിച്ച ഉത്തരവ് ഉടൻ നടപ്പിലാക്കുക എന്നത് പ്രധാന ആവശ്യങ്ങളിലൊന്നാണ്.', 'sv-demands', true),
('സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ലഘുലേഖയിൽ എത്ര ആവശ്യങ്ങളാണ് മുന്നോട്ടുവയ്ക്കുന്നത്?', '["7","5","10","12"]'::jsonb, 0, 'medium', 'Political', 'ശമ്പള പരിഷ്കരണം, NPS, ക്ഷാമബത്ത, ലീവ് സറണ്ടർ, സ്ഥലംമാറ്റം, മെഡിസെപ്, വിദ്യാഭ്യാസ-സർവീസ് മേഖല — 7 ആവശ്യങ്ങൾ.', 'sv-demands', true),
('NPS പിൻവലിച്ച് പഴയ പെൻഷൻ പുനഃസ്ഥാപിക്കുന്നതിനൊപ്പം ഏത് നിയമം പിൻവലിക്കണമെന്നാണ് സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ആവശ്യം?', '["PFRDA നിയമം","വിവരാവകാശ നിയമം","കേരള സർവീസ് ചട്ടങ്ങൾ","ലോക്പാൽ നിയമം"]'::jsonb, 0, 'medium', 'Political', '''എൻപിഎസ് പിൻവലിച്ച് പഴയ പെൻഷൻപദ്ധതി പുനഃസ്ഥാപിക്കുക; പിഎഫ്ആർഡിഎ നിയമം പിൻവലിക്കുക'' എന്നതാണ് ആവശ്യം.', 'sv-demand-pfrda', true),
('ശമ്പള പരിഷ്കരണം ഉടൻ നടപ്പിലാക്കുന്നതിനൊപ്പം സെക്രട്ടേറിയറ്റ് വളയൽ ആവശ്യപ്പെടുന്നത് എന്ത്?', '["ഇടക്കാലാശ്വാസം അനുവദിക്കുക","ബോണസ് ഇരട്ടിയാക്കുക","പ്രവൃത്തിസമയം കുറയ്ക്കുക","വിരമിക്കൽ പ്രായം കൂട്ടുക"]'::jsonb, 0, 'easy', 'Political', '''ശമ്പള പരിഷ്കരണം ഉടൻ നടപ്പിലാക്കുക; ഇടക്കാലാശ്വാസം അനുവദിക്കുക'' എന്നതാണ് ഒന്നാമത്തെ ആവശ്യം.', 'sv-demand-ir', true),
('സ്ഥലംമാറ്റവുമായി ബന്ധപ്പെട്ട് സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ആവശ്യം എന്ത്?', '["അന്യായമായ സ്ഥലംമാറ്റങ്ങൾ റദ്ദ് ചെയ്ത് പൊതു സ്ഥലംമാറ്റം മാനദണ്ഡ പ്രകാരം നടത്തുക","എല്ലാ ജീവനക്കാരെയും വർഷംതോറും മാറ്റുക","സ്ഥലംമാറ്റം പൂർണ്ണമായും നിർത്തുക","സ്ഥലംമാറ്റം നറുക്കെടുപ്പിലൂടെ മാത്രം"]'::jsonb, 0, 'medium', 'Political', 'അന്യായമായ സ്ഥലംമാറ്റങ്ങൾ റദ്ദ് ചെയ്യുക; പൊതു സ്ഥലംമാറ്റം മാനദണ്ഡ പ്രകാരം നടത്തുക.', 'sv-demand-transfer', true),
('''വിദ്യാഭ്യാസ-സർവീസ് മേഖലകൾ തകർക്കുന്ന നീക്കങ്ങൾ ഉപേക്ഷിക്കുക'' — ഇത് ഏത് സമരത്തിന്റെ ആവശ്യമാണ്?', '["2026 നവംബർ 21-ലെ സെക്രട്ടേറിയറ്റ് വളയൽ","2002-ലെ 32 ദിവസ പണിമുടക്ക്","1973-ലെ 54 ദിവസ പണിമുടക്ക്","2013-ലെ NPS വിരുദ്ധ പണിമുടക്ക്"]'::jsonb, 0, 'medium', 'Political', 'സെക്രട്ടേറിയറ്റ് വളയലിന്റെ ഏഴാമത്തെ ആവശ്യമാണിത്.', 'sv-demand-edu', true),
('സെക്രട്ടേറിയറ്റ് വളയലിലെ ആവശ്യങ്ങൾ ഉന്നയിച്ച് ആക്ഷൻ കൗൺസിൽ പ്രത്യക്ഷ സമരം ആരംഭിച്ചത് എന്ന്?', '["2024 ഡിസംബർ 6","2026 മേയ് 4","2025 ജനുവരി 1","2023 ഡിസംബർ 6"]'::jsonb, 0, 'medium', 'Political', '2024 ഡിസംബർ 6-നാണ് ആക്ഷൻ കൗൺസിൽ പ്രത്യക്ഷ സമരം ആരംഭിച്ചത്.', 'sv-agitation', true),
('സെക്രട്ടേറിയറ്റ് വളയലിന് മുമ്പ് ആക്ഷൻ കൗൺസിൽ നടത്തിയ പ്രക്ഷോഭങ്ങളിൽ ഉൾപ്പെടുന്നത്?', '["സെക്രട്ടേറിയറ്റ് മാർച്ച്, രാപ്പകൽ സമരം, സത്യാഗ്രഹം","ഓൺലൈൻ സർവേ മാത്രം","നിരാഹാരം മാത്രം","ഒരു പ്രക്ഷോഭവും നടത്തിയിട്ടില്ല"]'::jsonb, 0, 'easy', 'Political', 'സെക്രട്ടേറിയറ്റ് മാർച്ച്, രാപ്പകൽ സമരം, സത്യാഗ്രഹം തുടങ്ങി നിരവധി പ്രക്ഷോഭങ്ങൾ നടത്തി.', 'sv-agitation', true),
('ലഘുലേഖ പ്രകാരം കേരളത്തിൽ ഭരണമാറ്റം ഇല്ലായിരുന്നെങ്കിൽ ജീവനക്കാർക്ക് ലഭിക്കുമായിരുന്നത്?', '["പുതിയ ശമ്പളം, ഡിഎ കുടിശ്ശികയുടെ ഒരു ഗഡു, എപിഎസ്","പഴയ പെൻഷൻ മാത്രം","ബോണസ് മാത്രം","ഒന്നുമില്ല"]'::jsonb, 0, 'medium', 'Political', 'പുതിയ ശമ്പളം, ഡിഎ കുടിശ്ശികയുടെ ഒരു ഗഡു, എപിഎസ് (Assured Pension Scheme) എന്നിവ അനുഭവവേദ്യമാകുമായിരുന്നുവെന്ന് ലഘുലേഖ പറയുന്നു.', 'sv-what-if', true),
('12-ാം ശമ്പള പരിഷ്കരണം ഏത് തീയതി മുതൽ ലഭിക്കേണ്ടതാണ്?', '["01-07-2024","01-07-2019","01-04-2026","01-01-2025"]'::jsonb, 0, 'easy', 'Political', '1.7.2024 മുതൽ 12-ാം ശമ്പള പരിഷ്കരണം ലഭിക്കേണ്ടതാണ്.', 'sv-12th-due', false),
('01-07-2024 മുതൽ ലഭിക്കേണ്ട ശമ്പള പരിഷ്കരണം എത്രാമത്തേതാണ്?', '["12-ാം","10-ാം","11-ാം","13-ാം"]'::jsonb, 0, 'medium', 'Political', '11-ാം ശമ്പള പരിഷ്കരണം 1.7.2019 മുതലായിരുന്നു; അടുത്തത് 12-ാമത്തേത് 1.7.2024 മുതൽ.', 'sv-12th-due', false),
('11-ാം ശമ്പള പരിഷ്കരണം ഏത് തീയതി മുതൽ നടപ്പാക്കി?', '["01-07-2019","01-07-2014","01-07-2024","01-03-2002"]'::jsonb, 0, 'easy', 'Political', '1.7.2019 മുതലാണ് 11-ാം ശമ്പള പരിഷ്കരണം നടപ്പാക്കിയത്.', 'sv-11th', false),
('''10 വർഷം എന്തുചെയ്തു?'' എന്ന ചോദ്യത്തിന് മറുപടിയായി ലഘുലേഖ ചൂണ്ടിക്കാട്ടുന്ന ശമ്പള പരിഷ്കരണം ഏത്?', '["01-07-2019 മുതൽ 11-ാം ശമ്പള പരിഷ്കരണം","01-07-2004 മുതൽ 8-ാം ശമ്പള പരിഷ്കരണം","01-07-2024 മുതൽ 12-ാം ശമ്പള പരിഷ്കരണം","ഒരു ശമ്പള പരിഷ്കരണവും ഇല്ല"]'::jsonb, 0, 'medium', 'Political', 'കഴിഞ്ഞ 10 വർഷത്തിനിടയിലാണ് 1.7.19 മുതൽ 11-ാം ശമ്പള പരിഷ്കരണം നടപ്പാക്കിയത്.', 'sv-11th', false),
('12-ാം ശമ്പള കമ്മീഷനെ നിയമിച്ച ഉത്തരവ് ഏത്?', '["G.O(MS) 24/2026/Fin","G.O(MS) 37/2026/Fin","G.O(P) 38/2026/Fin","G.O(P) 44/2026/Fin"]'::jsonb, 0, 'hard', 'Political', 'G.O(MS) 24/2026/Fin (23.2.2026) പ്രകാരമാണ് 12-ാം ശമ്പള കമ്മീഷനെ നിയമിച്ചത്.', 'sv-commission', false),
('12-ാം ശമ്പള കമ്മീഷനെ നിയമിച്ച ഉത്തരവിന്റെ തീയതി?', '["23-02-2026","05-03-2026","28-02-2026","06-03-2026"]'::jsonb, 0, 'hard', 'Political', 'G.O(MS) 24/2026/Fin തീയതി 23.2.2026.', 'sv-commission', false),
('12-ാം ശമ്പള കമ്മീഷന്റെ പരിഗണനാ വിഷയങ്ങൾ (Terms of Reference) നിശ്ചയിച്ച ഉത്തരവ്?', '["GO(MS) 37/26 Fin dt. 5.3.26","GO(MS) 24/26 Fin dt. 23.2.26","GO(P) 38/26 Fin dt. 28.2.26","GO(P) 44/26 Fin dt. 6.3.26"]'::jsonb, 0, 'hard', 'Political', '1.7.2024 മുതൽ ശമ്പളം പരിഷ്കരിക്കാനുള്ള പരിഗണനാ വിഷയങ്ങൾ GO(MS) 37/26 Fin dt. 5.3.26 പ്രകാരം നിശ്ചയിച്ചു.', 'sv-tor', false),
('12-ാം ശമ്പള കമ്മീഷന്റെ പരിഗണനാ വിഷയങ്ങളിൽ ശമ്പള പരിഷ്കരണത്തിന് എത്ര വർഷ പ്രാബല്യമാണ് നിശ്ചയിച്ചത്?', '["5 വർഷം","10 വർഷം","3 വർഷം","7 വർഷം"]'::jsonb, 0, 'medium', 'Political', '5 വർഷ പ്രാബല്യം നിശ്ചയിച്ച പരിഗണനാ വിഷയങ്ങളാണ് ഉത്തരവായത്.', 'sv-agitation-result', false),
('12-ാം ശമ്പള കമ്മീഷനും 5 വർഷ പ്രാബല്യമുള്ള പരിഗണനാ വിഷയങ്ങളും ലഭിച്ചത് എന്തിന്റെ ഫലമായാണെന്ന് ലഘുലേഖ പറയുന്നു?', '["രണ്ടു വർഷത്തോളം നടത്തിയ പ്രക്ഷോഭത്തിന്റെ","ഒരു കോടതി വിധിയുടെ","കേന്ദ്ര നിർദ്ദേശത്തിന്റെ","ലോകബാങ്ക് ശുപാർശയുടെ"]'::jsonb, 0, 'medium', 'Political', 'കഴിഞ്ഞ രണ്ടു വർഷക്കാലത്തോളമായി നടത്തിവന്ന പ്രക്ഷോഭത്തിന്റെ കൂടി ഫലമാണിത്.', 'sv-agitation-result', false),
('ശമ്പള കമ്മീഷന്റെ പ്രവർത്തന തുടർച്ച സംബന്ധിച്ച ഫയൽ എത്ര കാലമായി മുഖ്യമന്ത്രിയുടെ അടുത്താണെന്നാണ് ലഘുലേഖ പറയുന്നത്?', '["മൂന്നര മാസം","ഒരു മാസം","ആറു മാസം","ഒരു വർഷം"]'::jsonb, 0, 'medium', 'Political', 'ഫയൽ മൂന്നര മാസക്കാലമായി മുഖ്യമന്ത്രിയുടെ അടുത്താണെന്ന് ലഘുലേഖ പറയുന്നു.', 'sv-file', false),
('ശമ്പള പരിഷ്കരണം എത്ര വർഷത്തിലൊരിക്കൽ മതി എന്ന അഭിപ്രായം മുഖ്യമന്ത്രി പ്രകടിപ്പിച്ചതായാണ് ലഘുലേഖ പറയുന്നത്?', '["10 വർഷം","5 വർഷം","3 വർഷം","7 വർഷം"]'::jsonb, 0, 'easy', 'Political', 'ശമ്പള പരിഷ്കരണം 10 വർഷത്തിലൊരിക്കൽ മതി എന്ന അഭിപ്രായം ധവളപത്രത്തിലും ബജറ്റിലും വ്യക്തമാക്കിയതായി ലഘുലേഖ പറയുന്നു.', 'sv-10yr', false),
('''ശമ്പള പരിഷ്കരണം 10 വർഷത്തിലൊരിക്കൽ'' എന്ന നിലപാട് വ്യക്തമാക്കിയത് എവിടെയെന്നാണ് ലഘുലേഖ പറയുന്നത്?', '["ധവളപത്രത്തിലും ബജറ്റിലും","ഗവർണറുടെ നയപ്രഖ്യാപനത്തിൽ മാത്രം","ശമ്പള കമ്മീഷൻ റിപ്പോർട്ടിൽ","ഹൈക്കോടതിയിലെ സത്യവാങ്മൂലത്തിൽ"]'::jsonb, 0, 'medium', 'Political', 'ധവളപത്രത്തിലും ബജറ്റിലും ഇത് വ്യക്തമാക്കിയതായി ലഘുലേഖ പറയുന്നു.', 'sv-10yr', false),
('ഇന്ത്യയിൽ 5 വർഷ തത്വമനുസരിച്ച് ശമ്പള പരിഷ്കരണം നടത്തുന്ന എത്ര സംസ്ഥാനങ്ങളിൽ ഒന്നാണ് കേരളം?', '["4","2","7","10"]'::jsonb, 0, 'medium', 'Political', '5 വർഷ തത്വമനുസരിച്ച് ശമ്പള പരിഷ്കരണം നടത്തുന്ന നാല് സംസ്ഥാനങ്ങളിലൊന്നാണ് കേരളം.', 'sv-5yr-states', false),
